	'front_c1_name' => 'Sofia Marín',
	'front_c1_p' => 'Leitete neun Jahre lang ein Personalteam in einem Lager, bevor sie 2012 Nami gründete, und begleitet noch die meisten ersten Morgen der Frühschicht selbst.',
	'front_c2_alt' => 'Porträt von Daniel Owusu',
