	'front_c2_name' => 'Daniel Owusu',
	'front_c2_p' => 'Kam 2015, um den Bereich Gesundheit aufzubauen. Weiß, welche Praxen eine Empfangskraft brauchen, die auch ein volles Wartezimmer beruhigen kann.',
	'front_c3_alt' => 'Porträt von Mei Lin',
